firestoreRules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isAuthenticated() {
      return request.auth != null;
    }
    function isDoctor() {
      return isAuthenticated() && (
        request.auth.token.email != null && (
          request.auth.token.email.lower() == 'comerconcalma@gmail.com' ||
          request.auth.token.email.lower() == 'cesaralmanza01@gmail.com'
        )
      );
    }
    match /cuestionarios_iniciales/{questionnaireId} {
      allow read: if true;
      allow create: if true;
      allow update: if true;
      allow delete: if isDoctor();
    }
    match /app_config/{docId} {
      allow read: if true;
      allow write: if isDoctor();
    }
    match /_system_config/{docId} {
      allow read, write: if isDoctor();
    }
  }
}
